window.kbPageData["views/entry/k-e4729357bacc3953"] = {"key":"entry/k-e4729357bacc3953","state":{"route":"entry/k-e4729357bacc3953"},"node":{"id":"k-e4729357bacc3953","mode":"k","title":"抽奖主办方按公布条件兑奖","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["抽奖主办方按已公布条件兑付奖项的义务"],"qs":["江苏 2024 B类 行测#20"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"抽奖主办方应按具有约束力的已公布条件兑现奖项。主办方在中奖后新增的兑奖负担，对中奖者无约束力。","review":{"definition":"抽奖主办方应按具有约束力的已公布条件兑现奖项。主办方在中奖后新增的兑奖负担，对中奖者无约束力。","explanation":"商场公布的特等奖是一年汽车使用权，宣传中未要求中奖者交押金或保险费。商场与厂商约定的付款要求由商场自行处理。因此，韩某有权取得一年使用权，兑付所需的10万元押金和保险费由商场支付，C项正确。","references":[],"evidence":"并未附加其他条件","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 B类 行测#20":{"paper":"江苏 2024 B类 行测","n":20,"mod":"常识判断","src":["0ae7ac475476e5635bd7.pdf",3],"asrc":["8dd171daee6fc74e9718.pdf",8],"card":"927aa3877fd16060dea20c45","links":[{"id":"k-e4729357bacc3953","role":"直接考查","why":"商场应按公布的条件交付汽车使用权，因此兑付所需的押金和保险费由商场承担。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-e4729357bacc3953":[["江苏 2024 B类 行测#20"]]}};
